// Showcase works: the shape scripts/import-works.ts writes into works.gen.ts, shared by Showcase and Home. Plain types and
// constants (no React, no TypeScript-only runtime syntax), so the Node importer can import this file under type stripping.
//
// Every work is one continuous take (no cuts) generated by Phasyn Studio with MiniMax H3 (8-step route, 1280×736 or
// 736×1280, 24 fps, sound generated with the picture), then upscaled 2× with Anime4K to the delivered master.

export const WORK_CATEGORIES = ['battle', 'daily', 'fantasy'] as const;
export type WorkCategory = (typeof WORK_CATEGORIES)[number];

export const WORK_ORIENTATIONS = ['landscape', 'portrait'] as const;
export type WorkOrientation = (typeof WORK_ORIENTATIONS)[number];

/** Feature chips a work can carry; labels per locale live in src/i18n/works.ts. Add a key there when adding one here. */
export const WORK_FEATURES = ['steps8', 'characterRef', 'softvl2x', 'oneTake', 'sound'] as const;
export type WorkFeature = (typeof WORK_FEATURES)[number];

export interface WorkTitle {
  'zh-hant': string;
  ja: string;
  en: string;
}

export interface WorkPoster {
  /** Site-relative URL of the largest variant. */
  src: string;
  srcSet: string;
  width: number;
  height: number;
}

export interface Work {
  slug: string;
  title: WorkTitle;
  /** The delivered JSON had no Japanese title: `title.ja` repeats the English one. */
  jaFallback: boolean;
  category: WorkCategory;
  orientation: WorkOrientation;
  seconds: number;
  fps: number;
  /** Size of the delivered (upscaled) master. */
  width: number;
  height: number;
  features: WorkFeature[];
  /** Short run id (first 8 characters). */
  run: string;
  seed: number;
  media: {
    /** 1280-wide H.264 copy, path relative to the media base (phones, default). */
    web: string;
    /** Full-size master copy, path relative to the media base (large screens). */
    hd: string;
    poster: WorkPoster;
  };
  /** 1 = first; null = not featured. */
  featured: number | null;
}
